const std = @import("std");

pub fn isTranslateCOutput(source: []const u8) bool {
    const prefix = source[0..@min(source.len, 32 * 1024)];
    if (std.mem.find(u8, prefix, "pub const __builtin_") == null or
        std.mem.find(u8, prefix, ".zig.c_builtins.") == null) return false;
    return std.mem.count(u8, prefix, "pub const __builtin_") >= 3;
}

/// Lines of the leading comment block that may carry a generated-file marker.
const header_lines = 16;

/// Whether the comment block at the top of `source` says a tool generated
/// the file: `@generated`, `DO NOT EDIT` (Go's `Code generated ... DO NOT
/// EDIT.` among them), a line starting `Autogenerated`, `Auto-generated`,
/// `Generated by` or `Code generated`, or `This file is generated` and its
/// variants. Only comments before the first line of code and within the
/// first few lines count, so code and prose that mention generation do not.
pub fn hasGeneratedHeader(source: []const u8) bool {
    var lines = std.mem.splitScalar(u8, source[0..@min(source.len, 4096)], '\n');
    var line_count: usize = 0;
    while (lines.next()) |line| : (line_count += 1) {
        if (line_count == header_lines) return false;
        const trimmed = std.mem.trim(u8, line, " \t\r");
        if (trimmed.len == 0) continue;
        if (!std.mem.startsWith(u8, trimmed, "//")) return false;
        const text = std.mem.trim(u8, std.mem.trimStart(u8, trimmed[2..], "/!"), " \t*");
        if (markerLine(text)) return true;
    }
    return false;
}

fn markerLine(text: []const u8) bool {
    for ([_][]const u8{ "@generated", "do not edit" }) |marker| {
        if (std.ascii.findIgnoreCase(text, marker) != null) return true;
    }
    for ([_][]const u8{ "autogenerated", "auto-generated", "generated by", "code generated" }) |prefix| {
        if (std.ascii.startsWithIgnoreCase(text, prefix)) return true;
    }
    for ([_][]const u8{ "this file is ", "this file was ", "this file has been ", "this is a ", "this is an " }) |lead| {
        const start = std.ascii.findIgnoreCase(text, lead) orelse continue;
        var rest = text[start + lead.len ..];
        for ([_][]const u8{ "automatically ", "auto-", "auto" }) |qualifier| {
            if (std.ascii.startsWithIgnoreCase(rest, qualifier)) {
                rest = rest[qualifier.len..];
                break;
            }
        }
        if (std.ascii.startsWithIgnoreCase(rest, "generated")) return true;
    }
    return false;
}

test "translate-c preambles are recognized without treating ordinary bindings as generated" {
    try std.testing.expect(isTranslateCOutput(
        "pub const __builtin_bswap16 = @import(\"std\").zig.c_builtins.__builtin_bswap16;\n" ++
            "pub const __builtin_bswap32 = @import(\"std\").zig.c_builtins.__builtin_bswap32;\n" ++
            "pub const __builtin_bswap64 = @import(\"std\").zig.c_builtins.__builtin_bswap64;\n",
    ));
    try std.testing.expect(!isTranslateCOutput("pub const __builtin_value = 1;\n"));
}

test "translate-c output skips file-local diagnostics" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const source: [:0]const u8 =
        "pub const __builtin_bswap16 = @import(\"std\").zig.c_builtins.__builtin_bswap16;\n" ++
        "pub const __builtin_bswap32 = @import(\"std\").zig.c_builtins.__builtin_bswap32;\n" ++
        "pub const __builtin_bswap64 = @import(\"std\").zig.c_builtins.__builtin_bswap64;\n" ++
        "fn generated() void { var value = 1; missing(value); }\n";
    const found = try @import("pipeline.zig").findings(arena.allocator(), source, @import("types.zig").Configuration.defaults());
    try std.testing.expectEqual(@as(usize, 0), found.len);
}

test "generated-file headers are recognized in the leading comments only" {
    const generated = [_][]const u8{
        "//! This file is auto-generated by tools/update_cpu_features.zig.\n\nconst std = @import(\"std\");\n",
        "//! This file is generated, do not edit manually! To generate, run:\n//! zig build gen-parser-oracle\n",
        "// Autogenerated: 'src/ExtractionOCaml/word_by_word_montgomery' --lang Zig\n",
        "//! This is a generated file, produced by nerd_font_codegen.py\n//! DO NOT EDIT BY HAND!\n",
        "//////////////////\n// This file was auto-generated by spec_parser.py //\n",
        "//! DO NOT EDIT\n//! Configuration options for ZLS.\n",
        "// Code generated by protoc-gen-zig. DO NOT EDIT.\n\npub const Message = struct {};\n",
        "// Copyright 2026 The Authors.\n// SPDX-License-Identifier: MIT\n\n// @generated by build.zig\n",
    };
    for (generated) |source| {
        errdefer std.debug.print("not recognized: {s}\n", .{source});
        try std.testing.expect(hasGeneratedHeader(source));
    }
    const written = [_][]const u8{
        // Mentions of generation in code or after it.
        "const std = @import(\"std\");\n/// This directory contains the generated file.\ngenerated_dir: u32,\n",
        "const text =\n    \\\\//! This file is auto-generated. Do not edit.\n;\n",
        // Prose in a module doc comment.
        "//! The purpose of `flags` is to parse CLI arguments.\n//! - Be an 80% solution: auto-generated help is out of scope.\n",
        "//! Generates the lookup tables at comptime.\n",
        "//! Every token is regenerated on each edit.\n",
        "",
    };
    for (written) |source| {
        errdefer std.debug.print("misrecognized: {s}\n", .{source});
        try std.testing.expect(!hasGeneratedHeader(source));
    }
}

test "generated files keep correctness findings but drop style findings" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const source: [:0]const u8 =
        "// Code generated by gen.zig. DO NOT EDIT.\n" ++
        "pub fn Bad_Name(allocator: anytype) !void {\n" ++
        "    const buffer = try allocator.alloc(u8, 4);\n" ++
        "    _ = buffer;\n" ++
        "}\n";
    var configuration = @import("types.zig").Configuration.defaults();
    configuration.levels[@backingInt(@import("types.zig").Rule.non_idiomatic_name)] = .warning;
    const found = try @import("pipeline.zig").findings(arena.allocator(), source, configuration);
    var saw_leak = false;
    for (found) |finding| {
        try std.testing.expect(finding.rule.tier() != .style);
        if (finding.rule == .unreleased_allocation) saw_leak = true;
    }
    try std.testing.expect(saw_leak);
}
